import json,sys
# Reconstruct what baseline was (we know from project files)
baseline = {
  'Api.csproj': {'System.Text.Json': '10.0.1', 'Azure.Identity': '1.13.2'},
  'Worker.csproj': {'Microsoft.Extensions.Hosting': '8.0.1', 'System.Text.Json': '8.0.4', 'OpenTelemetry.Extensions.Hosting': '1.15.0'},
  'Shared.csproj': {'System.Text.Json': '10.0.1', 'Azure.Identity': '1.11.4'},
  'Tests.csproj': {'xunit': '2.9.3', 'System.Text.Json': '10.0.1'}
}
after = json.load(sys.stdin)
print('CHANGES:')
for p in after.get('projects',[]):
    name=p['path'].split('/')[-1]
    for fw in p.get('frameworks',[]):
        for pkg in fw.get('topLevelPackages',[]):
            pid=pkg['id']
            ver=pkg.get('resolvedVersion','?')
            bver=baseline.get(name,{}).get(pid)
            if bver and bver != ver:
                print(f'  {name}: {pid} {bver} -> {ver}')
print()
print('UNCHANGED: all other packages resolve identically')
"

